{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@max10240/opencode-plugin-send-message-across-sessions",
  "version": "1.0.26",
  "description": "Send user-style messages between OpenCode sessions",
  "type": "module",
  "exports": {
    ".": "./dist/src/index.js",
    "./setup": "./dist/src/setup.js"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "build": "tsc -p tsconfig.build.json",
    "prepack": "node ../../scripts/sync-recommended-rules.mjs && npm run build"
  },
  "files": [
    "dist/**/*.js",
    "README.md",
    "README.zh-CN.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin"
  ],
  "author": "",
  "license": "ISC",
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.7"
  },
  "devDependencies": {
    "@copilotkit/aimock": "^1.42.1",
    "@types/bun": "^1.3.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.8.2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Max10240/opencode-plugin-unicorn.git",
    "directory": "packages/opencode-plugin-send-message-across-sessions"
  }
}
